1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	import org.springframework.samples.petclinic.util.MembershipLevels;
10	
11	/**
12	 * Captures the household level ceiling onto the freshly built {@link Owner} before it is saved.
13	 *
14	 * <p>A new owner's {@code membershipLevel} cannot exceed one above the current maximum membership
15	 * level among their existing household members — owners sharing the same non-blank
16	 * {@code householdId}. This step records that ceiling as {@link Owner#setMembershipLevelCap(Integer)}
17	 * ({@code max + 1}); the mapper later applies it via
18	 * {@link MembershipLevels#cappedLevelFor(Owner)}. With no existing household member the cap is left
19	 * unset, so no ceiling applies.
20	 *
21	 * <p>Runs after {@link AssignHousehold} (so the {@code householdId} is fixed) and before
22	 * {@link SaveOwner} (so the new owner — not yet persisted — is not counted among the existing
23	 * members).
24	 */
25	public class AssignMembershipLevelCap {
26	
27	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
